#!/usr/bin/env python3
"""Patches the android/ folder generated by `flutter create` for SplitEasy:
manifest (share targets, UPI visibility, label), minSdk, R8 shrinking, release signing.
Safe to re-run."""
import pathlib, re, shutil, sys

root = pathlib.Path(__file__).resolve().parent.parent
android = root / "android"
if not android.exists():
    sys.exit("android/ not found. Run `flutter create --platforms android .` first.")

# ---- AndroidManifest ----
mf = android / "app/src/main/AndroidManifest.xml"
s = mf.read_text()
s = re.sub(r'android:label="[^"]*"', 'android:label="SplitEasy"', s, count=1)
if "ACTION_SEND_PLACEHOLDER" not in s and "android.intent.action.SEND" not in s:
    share = """
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="image/*" />
            </intent-filter>
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="text/plain" />
            </intent-filter>
"""
    # insert before the closing tag of the first <activity>
    s = s.replace("</activity>", share + "        </activity>", 1)
    # launchMode singleTop so shares reach a running app
    s = re.sub(r'android:launchMode="[^"]*"', 'android:launchMode="singleTask"', s, count=1)
if "android:scheme=\"upi\"" not in s:
    s = s.replace("<queries>", '<queries>\n        <intent><action android:name="android.intent.action.VIEW" /><data android:scheme="upi" /></intent>', 1) \
        if "<queries>" in s else s.replace("</manifest>", """    <queries>
        <intent><action android:name="android.intent.action.VIEW" /><data android:scheme="upi" /></intent>
        <intent><action android:name="android.intent.action.TTS_SERVICE" /></intent>
    </queries>
</manifest>""")
mf.write_text(s)

# ---- proguard ----
shutil.copy(root / "android_overlay/proguard-rules.pro", android / "app/proguard-rules.pro")

# ---- gradle ----
kts = android / "app/build.gradle.kts"
groovy = android / "app/build.gradle"
if kts.exists():
    g = kts.read_text()
    if "key.properties" not in g:
        g = "import java.util.Properties\nimport java.io.FileInputStream\n" + g
        g = g.replace("android {", """val keystoreProps = Properties().apply {
    val f = rootProject.file("key.properties")
    if (f.exists()) load(FileInputStream(f))
}

android {""", 1)
        g = re.sub(r"(android \{)", r"""\1
    signingConfigs {
        create("release") {
            if (keystoreProps.containsKey("storeFile")) {
                keyAlias = keystoreProps["keyAlias"] as String
                keyPassword = keystoreProps["keyPassword"] as String
                storeFile = file(keystoreProps["storeFile"] as String)
                storePassword = keystoreProps["storePassword"] as String
            }
        }
    }""", g, count=1)
        g = re.sub(r"minSdk\s*=\s*(?:flutter\.minSdkVersion|2[0-3])\b", "minSdk = 24", g)
        g = re.sub(r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)',
                   '''signingConfig = if (keystoreProps.containsKey("storeFile")) signingConfigs.getByName("release") else signingConfigs.getByName("debug")
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")''', g)
    # receive_sharing_intent needs compileSdk 37 (Gradle metadata check fails on 36).
    g = re.sub(r"compileSdk\s*=\s*[^\n]+", "compileSdk = 37", g)
    kts.write_text(g)
elif groovy.exists():
    g = groovy.read_text()
    if "key.properties" not in g:
        g = g.replace("android {", """def keystoreProps = new Properties()
def kf = rootProject.file("key.properties")
if (kf.exists()) keystoreProps.load(new FileInputStream(kf))

android {
    signingConfigs {
        release {
            if (keystoreProps['storeFile']) {
                keyAlias keystoreProps['keyAlias']
                keyPassword keystoreProps['keyPassword']
                storeFile file(keystoreProps['storeFile'])
                storePassword keystoreProps['storePassword']
            }
        }
    }""", 1)
        g = re.sub(r"minSdkVersion\s+(?:flutter\.minSdkVersion|2[0-3]\b)", "minSdkVersion 24", g)
        g = re.sub(r"signingConfig\s+signingConfigs\.debug",
                   """signingConfig keystoreProps['storeFile'] ? signingConfigs.release : signingConfigs.debug
            minifyEnabled true
            shrinkResources true
            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'""", g)
    g = re.sub(r"compileSdk(?:Version)?\s*(?:=\s*)?[^\n]+", "compileSdk 37", g, count=1)
    groovy.write_text(g)
else:
    sys.exit("No app/build.gradle(.kts) found")
# AGP only "recommends" up to the SDK it was tested with; silence that warning for 37.
gp = android / "gradle.properties"
props = gp.read_text() if gp.exists() else ""
if "android.suppressUnsupportedCompileSdk" not in props:
    gp.write_text(props.rstrip("\n") + "\nandroid.suppressUnsupportedCompileSdk=37\n")

print("Android project patched.")
